/**
 * Smoke checks: the server and worker start with the documented commands and the health
 * endpoint responds. Run with `npm run build && npm run check:smoke`.
 */
import { waitForHealth, type Check } from './core.ts';

/** The brief allows each process 10 seconds to start, and the heartbeat must be under 3 seconds old. */
const STARTUP_MS = 10_000;

export const SMOKE_CHECKS: readonly Check[] = [
  {
    name: 'smoke.health',
    title: 'npm run start:server starts and GET /health returns 200 {"status":"ok"} within 10 s',
    async run(ctx) {
      await waitForHealth(ctx, STARTUP_MS, false);
    },
  },
  {
    name: 'smoke.worker-up',
    title: 'npm run start:worker starts and GET /health reports "worker":"up" within 10 s',
    async run(ctx) {
      await waitForHealth(ctx, STARTUP_MS, true);
    },
  },
];
/**
 * Shared machinery for the fixed build-time checks (`npm run check:smoke`, `npm run check:contract`).
 *
 * The checks use only the disclosed examples in this directory. Passing them does not mean the
 * task is complete: a separate, hidden evaluation with different cases decides acceptance.
 * Do not modify anything under checks/.
 */

export interface HttpRequest {
  method: string;
  path: string;
  headers?: Record<string, string>;
  /** Sent verbatim. No Content-Type is added unless given in `headers`. */
  body?: string;
}

export interface HttpResponse {
  status: number;
  contentType: string;
  text: string;
  /** Parsed body, or undefined when the body is not valid JSON. */
  json: unknown;
}

export interface HttpClient {
  request(req: HttpRequest): Promise<HttpResponse>;
}

export interface Clock {
  now(): number;
  sleep(ms: number): Promise<void>;
}

export interface App {
  /** Starts the server and worker. Does not wait for readiness. */
  start(): Promise<void>;
}

export interface CheckContext {
  http: HttpClient;
  clock: Clock;
  /** Absolute clock time after which waits stop early. */
  deadlineAt: number;
}

export interface Check {
  name: string;
  title: string;
  run(ctx: CheckContext): Promise<void>;
}

export interface CheckResult {
  name: string;
  title: string;
  passed: boolean;
