import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, MAX_ATTEMPTS, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;
let currentJobId: string | null = null;

const writeHeartbeat = db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at');
function heartbeat(): void {
  try {
    writeHeartbeat.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}

const nowIso = () => new Date().toISOString();

// Recover jobs left `running` by a worker that died. The interrupted attempt neither succeeded
// nor failed, so it is not counted; the job is requeued for immediate processing.
function recover(): void {
  const r = db
    .prepare(`UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ? WHERE status = 'running'`)
    .run(nowIso());
  if (Number(r.changes) > 0) console.log(`recovered ${r.changes} interrupted job(s)`);
}

const selectNext = db.prepare(
  `SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1`,
);
const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ? WHERE id = ? AND status = 'queued'`,
);
const getStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const progressStmt = db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', progress = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const retryStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const failStmt = db.prepare(
  `UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const releaseStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
);

function claim(): JobRow | null {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = selectNext.get(Date.now()) as JobRow | undefined;
    if (!row) {
      db.exec('COMMIT');
      return null;
    }
    const r = claimStmt.run(nowIso(), row.id);
    db.exec('COMMIT');
    if (Number(r.changes) !== 1) return null;
    return getStmt.get(row.id) as unknown as JobRow;
  } catch (err) {
    try { db.exec('ROLLBACK'); } catch { /* ignore */ }
    throw err;
  }
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  currentJobId = job.id;
  try {
    for (let step = 1; step <= job.steps; step++) {
      await sleep(STEP_MS);
      if (stopping) return; // released in shutdown()
      if (step === 1 && attempt <= job.fail_attempts) {
        if (attempt >= MAX_ATTEMPTS) {
          failStmt.run('transient failure', nowIso(), job.id);
          console.log(`job ${job.id} failed after ${attempt} attempts`);
        } else {
          retryStmt.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
          console.log(`job ${job.id} attempt ${attempt} failed; retrying`);
        }
        return;
      }
      if (step < job.steps) progressStmt.run(step, nowIso(), job.id);
    }
    completeStmt.run(job.input.toUpperCase(), nowIso(), job.id);
    console.log(`job ${job.id} completed`);
  } finally {
    currentJobId = null;
  }
}

function shutdown(): void {
  if (stopping) return;
  stopping = true;
  clearInterval(hbTimer);
  if (currentJobId) {
    try { releaseStmt.run(nowIso(), currentJobId); } catch (err) { console.error(err); }
  }
  try { db.close(); } catch { /* ignore */ }
  console.log('worker stopped');
  process.exit(0);
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

heartbeat();
const hbTimer = setInterval(heartbeat, HEARTBEAT_MS);
recover();
console.log('worker started');

while (!stopping) {
  let job: JobRow | null = null;
  try {
    job = claim();
  } catch (err) {
    console.error('claim failed', err);
  }
  if (job) {
    try {
      await processJob(job);
    } catch (err) {
      console.error('processing failed', err);
    }
  } else {
    await sleep(POLL_MS);
  }
}

