import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, HEARTBEAT_FRESH_MS, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const MAX_BODY = 1024 * 1024;

interface FieldError { field: string; message: string }

class HttpError extends Error {
  constructor(public status: number, public code: string, message: string, public fields?: FieldError[]) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(text), 'cache-control': 'no-store' });
  res.end(text);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  else if (err.code === 'invalid_request') error.fields = [];
  send(res, err.status, { error });
}

const invalid = (fields: FieldError[]) => new HttpError(400, 'invalid_request', 'The request is invalid.', fields);

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(c);
    });
    req.on('end', () => {
      if (tooLarge) reject(new HttpError(413, 'payload_too_large', 'Request body is too large.'));
      else resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

const stmts = {
  list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  get: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  byKey: db.prepare('SELECT * FROM jobs WHERE idem_key = ?'),
  insert: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idem_key, idem_payload)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
  ),
  heartbeat: db.prepare('SELECT at FROM heartbeat WHERE id = 1'),
};

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    const k = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
    if (!KEY_RE.test(k)) fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
    else key = k;
  }

  const ct = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const text = await readBody(req);
  const isJson = ct === 'application/json' || /^application\/[a-z0-9.!#$&^_-]+\+json$/.test(ct);
  if (!isJson) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    throw invalid(fields);
  }
  let body: unknown;
  try {
    body = JSON.parse(text);
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON.' });
    throw invalid(fields);
  }
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    throw invalid(fields);
  }
  const obj = body as Record<string, unknown>;
  for (const k of Object.keys(obj)) {
    if (k !== 'input' && k !== 'steps' && k !== 'failAttempts') fields.push({ field: k, message: 'Unknown field.' });
  }
  const input = obj.input;
  if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'input is required.' });
  else if (typeof input !== 'string') fields.push({ field: 'input', message: 'input must be a string.' });
  else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'input must be 1-1000 characters.' });
  else if (input.trim() === '') fields.push({ field: 'input', message: 'input must not be only whitespace.' });

  const intField = (name: string, min: number, max: number, def: number): number => {
    if (!Object.hasOwn(obj, name)) return def;
    const v = obj[name];
    if (typeof v !== 'number' || !Number.isInteger(v)) {
      fields.push({ field: name, message: `${name} must be an integer.` });
      return def;
    }
    if (v < min || v > max) {
      fields.push({ field: name, message: `${name} must be between ${min} and ${max}.` });
      return def;
    }
    return v;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);
  if (fields.length > 0) throw invalid(fields);

  const payload = JSON.stringify({ input, steps, failAttempts });
  const now = new Date().toISOString();
  const id = randomUUID();
  db.exec('BEGIN IMMEDIATE');
  let row: JobRow;
  let status = 201;
  try {
    const existing = key !== null ? (stmts.byKey.get(key) as (JobRow & { idem_payload: string }) | undefined) : undefined;
    if (existing) {
      if (existing.idem_payload !== payload) {
        db.exec('ROLLBACK');
